 1	import java.util.ArrayDeque;
 2	import java.util.Deque;
 3	
 4	public class BalancedParentheses {
 5	    private BalancedParentheses() {}
 6	
 7	    public static boolean isBalanced(String s) {
 8	        Deque<Character> brackets = new ArrayDeque<>();
 9	
10	        for (char c : s.toCharArray()) {
11	            if (isOpeningBracket(c)) {
12	                brackets.push(c);
13	                continue;
14	            }
15	
16	            if (isClosingBracket(c)) {
17	                if (brackets.isEmpty() || !isMatchingPair(brackets.pop(), c)) {
18	                    return false;
19	                }
20	            }
21	        }
22	
23	        return brackets.isEmpty();
24	    }
25	
26	    private static boolean isOpeningBracket(char c) {
27	        return c == '(' || c == '{' || c == '[';
28	    }
29	
30	    private static boolean isClosingBracket(char c) {
31	        return c == ')' || c == '}' || c == ']';
32	    }
33	
34	    private static boolean isMatchingPair(char opening, char closing) {
35	        return (opening == '(' && closing == ')')
36	            || (opening == '{' && closing == '}')
37	            || (opening == '[' && closing == ']');
38	    }
39	
40	    public static void main(String[] args) {
41	        String s = "[()()]{}";
42	        System.out.println((isBalanced(s) ? "true" : "false"));
43	    }
44	}

